CREATE OR REPLACE FUNCTION public.profile_shares_deal_with_me(p_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select (select auth.uid()) is not null and (
    exists (
      select 1 from public.conversations c
       where (c.participant_a = (select auth.uid()) and c.participant_b = p_id)
          or (c.participant_b = (select auth.uid()) and c.participant_a = p_id)
    )
    or exists (
      select 1 from public.orders o
       where (o.buyer_id = (select auth.uid()) and o.seller_id = p_id)
          or (o.seller_id = (select auth.uid()) and o.buyer_id = p_id)
    )
  );
$function$;

grant execute on function public.profile_shares_deal_with_me(p_id uuid) to anon;
grant execute on function public.profile_shares_deal_with_me(p_id uuid) to authenticated;
grant execute on function public.profile_shares_deal_with_me(p_id uuid) to service_role;
